`timescale 1ns/1ps
// =============================================================
// vhfastmulb16_add_bf16_bf16_bf16_rne_lat4_rand_tb.v
// Random/directed regression for vhfastmulb16_add_bf16_bf16_bf16_rne_lat4.
//
// Vectors are generated by scripts/gen_bf16_vectors.py into
// build/vhfastmulb16_add_bf16_bf16_bf16_rne_lat4_rand.hex
// (one 48-bit word per line):
//   [47:32] = BF16 A
//   [31:16] = BF16 B
//   [15:0]  = expected BF16 sum (RNE)
//
// The stream test uses LAT = 4 and checks pair k-LAT on cycle k.
// Also checks en=0 HOLD and reset priority.
// =============================================================

module vhfastmulb16_add_bf16_bf16_bf16_rne_lat4_rand_tb;

    localparam integer N         = 4096;  // must match generator --count
    localparam integer LAT       = 4;
    localparam integer MAX_PRINT = 20;
    localparam integer VEC_FILE_LINES = N;

    reg         clk;
    reg         reset;
    reg         en;
    reg  [15:0] ibf16a;
    reg  [15:0] ibf16b;
    wire [15:0] obf16c;

    vhfastmulb16_add_bf16_bf16_bf16_rne_lat4 uut (
        .clk     (clk),
        .reset   (reset),
        .en      (en),
        .ibf16a  (ibf16a),
        .ibf16b  (ibf16b),
        .obf16c  (obf16c)
    );

    reg [47:0] vec [0:N-1];

    integer k;
    integer checked;
    integer errors;
    reg [15:0] hold_val;

    task check;
        input integer idx;
        reg [15:0] va;
        reg [15:0] vb;
        reg [15:0] ve;
        begin
            va = vec[idx][47:32];
            vb = vec[idx][31:16];
            ve = vec[idx][15:0];
            checked = checked + 1;
            if (obf16c !== ve) begin
                errors = errors + 1;
                if (errors <= MAX_PRINT) begin
                    $display("[ERROR] t=%0t | pair %0d | a=%h b=%h",
                             $time, idx, va, vb);
                    $display("        exp: obf16c=%h | got: obf16c=%h", ve, obf16c);
                end
            end
        end
    endtask

    // ---------------- Clock generation 100 MHz ----------------
    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    // ---------------- RESET: 5 clk ----------------
    initial begin
        reset  = 1'b1;
        en     = 1'b0;
        ibf16a = 16'h0000;
        ibf16b = 16'h0000;
        repeat (5) @(negedge clk);
        reset = 1'b0;
    end

    // ---------------- Main scenario ----------------
    initial begin
        $dumpfile("build/vhfastmulb16_add_bf16_bf16_bf16_rne_lat4_rand.vcd");
        $dumpvars(0, vhfastmulb16_add_bf16_bf16_bf16_rne_lat4_rand_tb);

        $readmemh("build/vhfastmulb16_add_bf16_bf16_bf16_rne_lat4_rand.hex",
                  vec, 0, VEC_FILE_LINES - 1);

        checked = 0;
        errors  = 0;

        // Wait for reset release + 10 clocks.
        @(negedge reset);
        repeat (10) @(negedge clk);

        if (obf16c !== 16'h0000) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | after reset: exp obf16c=0000, got obf16c=%h",
                     $time, obf16c);
        end

        // Stream N pairs, one per clock. Result of pair k appears on k+4.
        for (k = 0; k < N + LAT; k = k + 1) begin
            @(posedge clk);
            #1;

            if (k < N) begin
                ibf16a = vec[k][47:32];
                ibf16b = vec[k][31:16];
                en     = 1'b1;
            end else begin
                en = 1'b0;
            end

            if (k >= LAT)
                check(k - LAT);
        end

        // ---- en=0 HOLD ----
        en     = 1'b0;
        ibf16a = 16'h7FC1;
        ibf16b = 16'h3F80;
        @(posedge clk);
        #1;
        hold_val = obf16c;
        repeat (6) @(posedge clk);
        #1;
        if (obf16c !== hold_val) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | en=0 hold: exp obf16c=%h, got obf16c=%h",
                     $time, hold_val, obf16c);
        end

        // ---- reset priority over en ----
        en    = 1'b1;
        reset = 1'b1;
        @(posedge clk);
        #1;
        if (obf16c !== 16'h0000) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | reset priority: exp obf16c=0000, got obf16c=%h",
                     $time, obf16c);
        end
        reset = 1'b0;
        en    = 1'b0;

        // Final nop cycles.
        repeat (10) @(posedge clk);
        #1;

        $display("---------------------------------------------");
        $display("Checked vectors: %0d", checked);
        $display("Errors:          %0d", errors);
        if (errors == 0)
            $display("TEST PASSED");
        else
            $display("TEST FAILED");
        $display("---------------------------------------------");
        $finish;
    end

    // ---------------- Watchdog ----------------
    initial begin
        #10000000;
        $display("[ERROR] Testbench timeout!");
        $finish;
    end

endmodule
